func TestGettersLoadBalancerCreate(t *testing.T) {
	t.Run("GetLoadBalancerCreateZero", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &LoadBalancerCreate{}
		var expected *LoadBalancerCreateZero
		obj.LoadBalancerCreateZero = expected

		// Act & Assert
		assert.Equal(t, expected, obj.GetLoadBalancerCreateZero(), "getter should return the property value")
	})

	t.Run("GetLoadBalancerCreateZero_NilValue", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &LoadBalancerCreate{}
		obj.LoadBalancerCreateZero = nil

		// Act & Assert
		assert.Nil(t, obj.GetLoadBalancerCreateZero(), "getter should return nil when property is nil")
	})

	t.Run("GetLoadBalancerCreateZero_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *LoadBalancerCreate
		// Should not panic - getters should handle nil receiver gracefully
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("Getter panicked on nil receiver: %v", r)
			}
		}()
		_ = obj.GetLoadBalancerCreateZero() // Should return zero value
	})

	t.Run("GetLoadBalancerCreateOne", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &LoadBalancerCreate{}
		var expected *LoadBalancerCreateOne
		obj.LoadBalancerCreateOne = expected

		// Act & Assert
		assert.Equal(t, expected, obj.GetLoadBalancerCreateOne(), "getter should return the property value")
	})

	t.Run("GetLoadBalancerCreateOne_NilValue", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &LoadBalancerCreate{}
		obj.LoadBalancerCreateOne = nil

		// Act & Assert
		assert.Nil(t, obj.GetLoadBalancerCreateOne(), "getter should return nil when property is nil")
	})

	t.Run("GetLoadBalancerCreateOne_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *LoadBalancerCreate
		// Should not panic - getters should handle nil receiver gracefully
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("Getter panicked on nil receiver: %v", r)
			}
		}()
		_ = obj.GetLoadBalancerCreateOne() // Should return zero value
	})

}

